def recalibrate(p, keep):
    return p * keep / (p * keep + (1 - p))

true_ctr, keep = 0.02, 0.1
p_train = true_ctr / (true_ctr + (1 - true_ctr) * keep)
print(round(p_train, 4), round(recalibrate(p_train, keep), 4))
# 0.1695 0.02

import random
random.seed(7)
true = {"old": 0.05, "new": 0.08}
a = {"old": [1, 1], "new": [1, 1]}
shown = {"old": 0, "new": 0}
for _ in range(2000):
    pick = max(a, key=lambda k: random.betavariate(*a[k]))
    shown[pick] += 1
    a[pick][0 if random.random() < true[pick] else 1] += 1
print(shown)
# {'old': 211, 'new': 1789}
